const s={ui:{fig:"Fig. 2",title:"Extrémités finies",svgLabel:"Un dessin isométrique pour finir les extrémités d'une fermeture éclair avec des languettes de tissu : une bande un peu plus large que le ruban de la fermeture éclair pliée comme un biais, deux bords au milieu puis en deux ; glissée sur chaque extrémité de la fermeture et piquée le long des bords rabattus, juste après l'arrêt, jamais dessus.",prev:"Étape précédente",dot:(e,t)=>e?`Étape ${e} : ${t}`:t,start:"Étapes →",next:"Suivant →",overview:"Vue d'ensemble",stepOf:(e,t)=>`Étape ${e} sur ${t}`,machine:e=>`Machine : ${e.toLowerCase()}`,inThisStep:"Pour cette étape",takeApart:"Soulever les languettes",putTogether:"Remettre les languettes",replay:"↻ Revoir",parts:"Pièces",allSteps:"Instructions étape par étape",endView:"VUE EN COUPE"},stitches:{straight:"Point droit"},labels:{strip:"une bande de tissu",widerThanTape:"un peu plus large que le ruban",edgesMiddle:"bords au milieu",press:"repasser",inHalf:"plier en deux",slipOn:"sur l'extrémité du zip",pastStop:"juste après l'arrêt",alongEdge:"le long des bords pliés",notOverStop:"pas sur l'arrêt",otherEnd:"l'autre extrémité, pareil",thenLined:"ensuite comme la première façon"},steps:[{title:"Extrémités finies",text:"Les deux extrémités de la fermeture éclair sont finies par de petites languettes de tissu, piquées juste après les arrêts. Touchez pour soulever les languettes."},{title:"Une bande de tissu",text:"Coupez une bande de tissu un peu plus large que le ruban de la fermeture éclair, une pour chaque extrémité.",details:["Coupez une courte bande de tissu un peu plus large que le ruban de la fermeture éclair : la languette couvre le bout de la fermeture d'un bord à l'autre.","Il en faut deux : une pour chaque extrémité de la fermeture.","Chaque patron donne une taille différente ; l'essentiel est que la bande soit un peu plus large que le ruban de la fermeture éclair."]},{title:"Bords au milieu",text:"Posez la bande envers dessus, rabattez deux bords opposés jusqu'au milieu et repassez, comme un biais.",details:["Posez la bande envers dessus.","Rabattez deux bords opposés pour qu'ils se rejoignent au milieu, envers contre envers.","Repassez les plis."]},{title:"Plier en deux",text:"Pliez la bande en deux au milieu, les bords rabattus à l'intérieur, et repassez. La languette est prête : un pli d'un côté, les bords rabattus de l'autre.",details:["Pliez la bande en deux au milieu, pour que les bords rabattus se retrouvent à l'intérieur.","Repassez : la languette a maintenant un pli d'un côté et les deux bords rabattus de l'autre.","Faites la deuxième languette de la même façon."]},{title:"Sur l'extrémité",text:"Glissez la languette sur l'extrémité de la fermeture éclair : le bout entre à l'intérieur jusqu'au pli, et les bords rabattus arrivent juste après l'arrêt.",details:["Ouvrez un peu la languette et glissez-y le bout de la fermeture, jusqu'au pli.","Les bords rabattus arrivent juste après l'arrêt, pas dessus.","La languette dépasse un peu de chaque côté de la fermeture."]},{title:"Piquer la languette",text:"Avec le pied fermeture éclair, piquez le long des bords rabattus, à travers la languette et le ruban. Ne cousez jamais sur l'arrêt ni sur les dents.",details:["Mettez le pied fermeture éclair : il permet de piquer près des bords rabattus.","Piquez en travers de la languette, près des bords rabattus, à travers toutes ses épaisseurs et le ruban.","La piqûre reste sur le ruban, après l'arrêt : ne cousez jamais sur l'arrêt ni sur les dents. Ils sont souvent en métal, et l'aiguille peut casser."]},{title:"L'autre extrémité",text:"Glissez la deuxième languette sur l'autre extrémité et piquez-la de la même façon, au pied fermeture éclair, après l'arrêt. Ensuite, la fermeture se coud comme la fermeture éclair en sandwich.",details:["Glissez la deuxième languette sur l'autre extrémité de la fermeture, les bords rabattus juste après l'arrêt.","Au pied fermeture éclair, piquez le long des bords rabattus, pas sur l'arrêt.","La suite se coud comme la première façon, la fermeture éclair en sandwich : le lien est sous ce dessin."]}],legend:[{title:"Languette",text:"bande de tissu pliée comme un biais · un peu plus large que le ruban"},{title:"Piqûre",text:"le long des bords rabattus, après l'arrêt"},{title:"Arrêt",text:"jamais cousu dessus"},{title:"Fermeture éclair",text:"ses bouts dans les languettes"}]};export{s as default};
